#!/usr/bin/env node
// scripts/inject-release-key.js
//
// Bakes RELEASES_WRITE_KEY into src/main/config.generated.ts at build time,
// so a packaged Electron .app (which inherits no shell environment when
// launched from Finder) still has a real write key. Runs automatically on
// `npm install` (postinstall) and again before `tsc` compiles src/main as
// part of `npm run dist`:
//
//   RELEASES_WRITE_KEY=xxxxxxxx npm run dist
//
// config.generated.ts is gitignored — it's a build artifact, regenerated by
// this script, and must never carry a real secret into version control.
//
// If RELEASES_WRITE_KEY is not set in the environment, this (re)writes
// config.generated.ts with its null placeholder, so config.ts falls back to
// its dev-time process.env.RELEASES_WRITE_KEY override (or the "not
// configured" placeholder key, which the server rejects with 401).
//
// See src/main/config.ts for the full resolution order and the
// "Distributing a real build" section in README.md.
'use strict';

const fs = require('fs');
const path = require('path');

const TARGET = path.join(__dirname, '..', 'src', 'main', 'config.generated.ts');

function render(value) {
  const literal = value === null ? 'null' : JSON.stringify(value);
  return `// GENERATED FILE — do not edit by hand.
//
// Written by scripts/inject-release-key.js from the RELEASES_WRITE_KEY
// build-time environment variable. See src/main/config.ts for how this is
// consumed and the "Distributing a real build" section in README.md for
// how to set RELEASES_WRITE_KEY when packaging a real build.
export const INJECTED_RELEASES_WRITE_KEY: string | null = ${literal};
`;
}

const key = process.env.RELEASES_WRITE_KEY;

if (key) {
  fs.writeFileSync(TARGET, render(key));
  console.log('[inject-release-key] baked RELEASES_WRITE_KEY into src/main/config.generated.ts');
} else {
  fs.writeFileSync(TARGET, render(null));
  console.log(
    '[inject-release-key] RELEASES_WRITE_KEY not set in the build environment — ' +
      'config.generated.ts reset to its null placeholder (dev-time env var fallback still applies).',
  );
}
